class TenantOperationActionsCreateView(View):
    template_name = 'iroad_tenants/Operation_management/Operation_Action/Operation-actions.html'

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            context.update(_tenant_operation_action_form_context(tenant_registry))
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()

    def post(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            form_data = {
                'arabic_label': (request.POST.get('arabic_label') or '').strip(),
                'english_label': (request.POST.get('english_label') or '').strip(),
                'status': (request.POST.get('status') or '').strip(),
                'action_scope': (request.POST.get('action_scope') or '').strip(),
                'sequence_category': (request.POST.get('sequence_category') or '').strip(),
                'sequence_number': (request.POST.get('sequence_number') or '').strip(),
                'booking_status_impact': (request.POST.get('booking_status_impact') or '').strip(),
                'shipment_status_impact': (request.POST.get('shipment_status_impact') or '').strip(),
                'movement_status_impact': (request.POST.get('movement_status_impact') or '').strip(),
                'auto_movement_post': request.POST.get('auto_movement_post') == 'on',
                'auto_shipment_post': request.POST.get('auto_shipment_post') == 'on',
                'auto_pod_post': request.POST.get('auto_pod_post') == 'on',
                'hard_copy_collection': request.POST.get('hard_copy_collection') == 'on',
            }
            form_errors = {}
            required_fields = {
                'english_label': 'English Label is required.',
                'status': 'Status is required.',
                'action_scope': 'Action Scope is required.',
                'sequence_category': 'Sequence Category is required.',
                'sequence_number': 'Sequence Number is required.',
            }
            for field_name, message in required_fields.items():
                if not form_data[field_name]:
                    form_errors[field_name] = message

            valid_statuses = {value for value, _ in TenantOperationAction.Status.choices}
            if form_data['status'] and form_data['status'] not in valid_statuses:
                form_errors['status'] = 'Invalid status selected.'

            valid_scopes = {'job', 'on_call', 'without'}
            if form_data['action_scope'] and form_data['action_scope'] not in valid_scopes:
                form_errors['action_scope'] = 'Invalid action scope selected.'

            try:
                sequence_number = int(form_data['sequence_number'] or '0')
                if sequence_number < 1:
                    raise ValueError
            except ValueError:
                sequence_number = 1
                form_errors['sequence_number'] = 'Sequence Number must be 1 or greater.'

            if form_errors:
                context.update(
                    _tenant_operation_action_form_context(
                        tenant_registry,
                        form_data=form_data,
                        form_errors=form_errors,
                    )
                )
                messages.error(request, 'Please fix the highlighted action fields.', extra_tags='tenant')
                return render(request, self.template_name, context)

            try:
                with db_transaction.atomic():
                    action_code = ''
                    for _ in range(10):
                        action_code, _ = _next_auto_number_for_form(
                            form_code=OPERATION_ACTION_AUTO_FORM_CODE,
                            form_label=OPERATION_ACTION_AUTO_FORM_LABEL,
                            prefix=OPERATION_ACTION_REF_PREFIX,
                        )
                        if not TenantOperationAction.objects.filter(action_code=action_code).exists():
                            break
                    if TenantOperationAction.objects.filter(action_code=action_code).exists():
                        raise ValueError(
                            'Unable to allocate a unique Action Code. Please check Auto Number Configuration.'
                        )

                    action = TenantOperationAction.objects.create(
                        action_code=action_code,
                        arabic_label=form_data['arabic_label'],
                        english_label=form_data['english_label'],
                        status=form_data['status'],
                        action_scope=form_data['action_scope'],
                        sequence_category=form_data['sequence_category'],
                        sequence_number=sequence_number,
                        auto_movement_post=form_data['auto_movement_post'],
                        auto_shipment_post=form_data['auto_shipment_post'],
                        auto_pod_post=form_data['auto_pod_post'],
                        hard_copy_collection=form_data['hard_copy_collection'],
                        booking_status_impact=form_data['booking_status_impact'],
                        shipment_status_impact=form_data['shipment_status_impact'],
                        movement_status_impact=form_data['movement_status_impact'],
                    )
            except (IntegrityError, ValueError) as exc:
                context.update(
                    _tenant_operation_action_form_context(
                        tenant_registry,
                        form_data=form_data,
                        form_errors={'action_code': str(exc)},
                    )
                )
                messages.error(request, str(exc), extra_tags='tenant')
                return render(request, self.template_name, context)

            messages.success(request, f'Operation action {action.action_code} created successfully.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_operation_actions_list')
        finally:
            connection.set_schema_to_public()


def _tenant_surcharge_sales_booking_display_label(shipment):
    if not shipment or not shipment.booking_id:
        return ''
    booking_no = shipment.booking.booking_no if shipment.booking else ''
    parts = [part for part in [booking_no, (shipment.booking_item_ref or '').strip()] if part]
    return ' - '.join(parts) or booking_no


def _tenant_surcharge_sales_currency_from_shipment(shipment):
    if shipment and shipment.client_account_id and shipment.client_account:
        return (shipment.client_account.preferred_currency or 'SAR')[:8]
    return 'SAR'


def _tenant_surcharge_sales_sync_derived_display(form_data, shipment):
    """Default empty FK fields from shipment; refresh display labels from current FK ids."""
    if not shipment:
        return
    if not (form_data.get('booking_id') or '').strip() and shipment.booking_id:
        form_data['booking_id'] = str(shipment.booking_id)
    if not (form_data.get('client_account_id') or '').strip() and shipment.client_account_id:
        form_data['client_account_id'] = str(shipment.client_account_id)
    if not (form_data.get('currency_code') or '').strip():
        currency_code = _tenant_surcharge_sales_currency_from_shipment(shipment)
        form_data['currency_code'] = currency_code
        form_data['currency'] = currency_code
    booking_id = (form_data.get('booking_id') or '').strip()
    if booking_id:
        booking = TenantBooking.objects.filter(pk=booking_id).first()
        if booking:
            parts = [booking.booking_no]
            form_data['booking_ref'] = ' - '.join(parts) or booking.booking_no
    elif shipment.booking_id:
        form_data['booking_ref'] = _tenant_surcharge_sales_booking_display_label(shipment)
    client_id = (form_data.get('client_account_id') or '').strip()
    if client_id:
        client = TenantClientAccount.objects.filter(pk=client_id).first()
        if client:
            form_data['client'] = client_account_label(client)
    elif shipment.client_account_id:
        form_data['client'] = client_account_label(shipment.client_account)
    currency_code = (form_data.get('currency_code') or '').strip()
    if currency_code:
        form_data['currency'] = currency_code


def _tenant_surcharge_sales_form_data_from_surcharge(surcharge):
    shipment = surcharge.shipment
    unit_price = surcharge.unit_price
    if (not unit_price or unit_price == 0) and surcharge.qty:
        unit_price = (surcharge.subtotal / surcharge.qty).quantize(Decimal('0.01'))
    form_data = {
        'surcharge_id': str(surcharge.surcharge_id),
        'page_mode': 'edit',
        'trx_date': surcharge.transaction_date.isoformat() if surcharge.transaction_date else '',
        'shipment_id': str(shipment.shipment_id),
        'booking_id': str(surcharge.booking_id) if surcharge.booking_id else '',
        'client_account_id': str(surcharge.client_account_id) if surcharge.client_account_id else '',
        'service_item_id': str(surcharge.service_item_id) if surcharge.service_item_id else '',
        'description': surcharge.description,
        'quantity': str(surcharge.qty),
        'unit_price': str(unit_price),
        'total_amount': str(surcharge.subtotal),
        'status': surcharge.status or TenantShipmentSurcharge.Status.DRAFT,
        'notes': surcharge.reason,
    }
    _tenant_surcharge_sales_sync_derived_display(form_data, shipment)
    return form_data


def _tenant_surcharge_sales_apply_foreign_keys(
    surcharge,
    *,
    shipment,
    service_item,
    booking_id='',
    client_account_id='',
    currency='',
):
    """Persist FK relations from form (user may override shipment defaults)."""
    surcharge.shipment_id = shipment.shipment_id
    surcharge.service_item_id = service_item.service_item_id
    resolved_booking_id = (booking_id or '').strip() or (
        str(shipment.booking_id) if shipment.booking_id else ''
    )
    resolved_client_id = (client_account_id or '').strip() or (
        str(shipment.client_account_id) if shipment.client_account_id else ''
    )
    surcharge.booking_id = resolved_booking_id or None
    surcharge.client_account_id = resolved_client_id or None
    surcharge.currency = (currency or _tenant_surcharge_sales_currency_from_shipment(shipment))[:8]


def _tenant_surcharge_sales_validate_submission(request, form_data, *, existing_surcharge=None):
    form_errors = {}
    if form_data.get('surcharge_id') and existing_surcharge is None:
        form_errors['surcharge_id'] = 'Surcharge transaction not found.'

    transaction_date = None
    if not (form_data.get('trx_date') or '').strip():
        form_errors['trx_date'] = 'Transaction date is required.'
    else:
        transaction_date = parse_date(form_data['trx_date'])
        if transaction_date is None:
            form_errors['trx_date'] = 'Transaction date must be a valid date.'

    shipment = None
    if not (form_data.get('shipment_id') or '').strip():
        form_errors['shipment_id'] = 'Shipment is required.'
    else:
        shipment = (
            TenantShipment.objects.select_related('booking', 'client_account')
            .exclude(shipment_status=TenantShipment.ShipmentStatus.CANCELLED)
            .filter(pk=form_data['shipment_id'])
            .first()
        )
        if shipment is None:
            form_errors['shipment_id'] = 'Select a valid shipment.'
        else:
            posted_booking_id = (form_data.get('booking_id') or '').strip()
            posted_client_id = (form_data.get('client_account_id') or '').strip()
            posted_currency = (form_data.get('currency_code') or '').strip().upper()[:8]
            if not posted_booking_id and shipment.booking_id:
                posted_booking_id = str(shipment.booking_id)
                form_data['booking_id'] = posted_booking_id
            if not posted_client_id and shipment.client_account_id:
                posted_client_id = str(shipment.client_account_id)
                form_data['client_account_id'] = posted_client_id
            if not posted_currency:
                posted_currency = _tenant_surcharge_sales_currency_from_shipment(shipment)
                form_data['currency_code'] = posted_currency
            if posted_booking_id:
                booking = (
                    TenantBooking.objects.exclude(
                        booking_status=TenantBooking.Status.CANCELLED,
                    )
                    .filter(pk=posted_booking_id)
                    .first()
                )
                if booking is None:
                    form_errors['booking_id'] = 'Select a valid booking.'
                else:
                    form_data['booking_ref'] = booking.booking_no
            if posted_client_id:
                client = TenantClientAccount.objects.filter(
                    pk=posted_client_id,
                    status=TenantClientAccount.Status.ACTIVE,
                ).first()
                if client is None:
                    form_errors['client_account_id'] = 'Select a valid active client.'
                else:
                    form_data['client'] = client_account_label(client)
            if posted_currency:
                form_data['currency_code'] = posted_currency
                if not Currency.objects.filter(currency_code=posted_currency, is_active=True).exists():
                    form_errors['currency_code'] = 'Select a valid active currency.'
            _tenant_surcharge_sales_sync_derived_display(form_data, shipment)

    service_item = None
    if not (form_data.get('service_item_id') or '').strip():
        form_errors['service_item_id'] = 'Service is required.'
    else:
        service_item = TenantServiceItemMaster.objects.filter(
            pk=form_data['service_item_id'],
            service_type=TenantServiceItemMaster.ServiceType.SERVICE,
            status=TenantServiceItemMaster.Status.ACTIVE,
        ).first()
        if service_item is None:
            form_errors['service_item_id'] = 'Select a valid service item.'

    valid_statuses = {value for value, _ in TenantShipmentSurcharge.Status.choices}
    if form_data.get('status') not in valid_statuses:
        form_errors['status'] = 'Invalid status selected.'

    quantity = Decimal('0')
    try:
        quantity = Decimal(form_data.get('quantity') or '0')
        if quantity <= 0:
            raise ValueError
    except Exception:
        form_errors['quantity'] = 'Quantity must be greater than zero.'

    unit_price = Decimal('0')
    try:
        unit_price = Decimal(form_data.get('unit_price') or '0')
        if unit_price < 0:
            raise ValueError
    except Exception:
        form_errors['unit_price'] = 'Unit price must be zero or greater.'

    if (
        form_data.get('status') == TenantShipmentSurcharge.Status.CONFIRMED
        and unit_price <= 0
    ):
        form_errors['unit_price'] = 'Unit price must be greater than zero for confirmed transactions.'

    if not (form_data.get('notes') or '').strip():
        form_errors['notes'] = 'Reason is required.'

    upload = request.FILES.get('attachment_file')
    if upload is None and existing_surcharge is None:
        form_errors['attachment_file'] = 'Attachment is required.'

    _tenant_surcharge_sales_guard_status(
        existing_surcharge,
        form_data.get('status'),
        form_errors,
        request,
    )
    if (
        form_data.get('status') == TenantShipmentSurcharge.Status.CONFIRMED
        and not form_errors.get('attachment_file')
        and upload is None
        and (existing_surcharge is None or not existing_surcharge.attachment_file)
    ):
        form_errors['attachment_file'] = 'Attachment is required before confirming.'

    currency = (form_data.get('currency_code') or '').strip()[:8]
    if not currency and shipment is not None:
        currency = _tenant_surcharge_sales_currency_from_shipment(shipment)
    total_amount = (quantity * unit_price).quantize(Decimal('0.01'))
    return form_errors, transaction_date, shipment, service_item, quantity, unit_price, total_amount, currency, upload


class TenantOperationSurchargeSalesListView(View):
    template_name = 'iroad_tenants/Operation_management/Surcharge/Surcharge-sales-transaction.html'

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            search_q = (request.GET.get('q') or '').strip()
            surcharge_qs = TenantShipmentSurcharge.objects.select_related(
                'shipment',
                'booking',
                'client_account',
                'service_item',
            ).order_by('-created_at')
            if search_q:
                surcharge_qs = surcharge_qs.filter(
                    Q(transaction_no__icontains=search_q)
                    | Q(item_label__icontains=search_q)
                    | Q(shipment__shipment_no__icontains=search_q)
                    | Q(shipment__booking__booking_no__icontains=search_q)
                    | Q(client_account__account_no__icontains=search_q)
                    | Q(client_account__display_name__icontains=search_q)
                )

            paginator = Paginator(surcharge_qs, 25)
            page_obj = paginator.get_page(request.GET.get('page') or 1)
            surcharge_rows = []
            for surcharge in page_obj.object_list:
                shipment = surcharge.shipment
                service_label = surcharge.item_label
                if surcharge.service_item_id:
                    service_label = (
                        f'{surcharge.service_item.service_code} - {surcharge.service_item.english_name}'
                    )
                status_label = dict(TenantShipmentSurcharge.Status.choices).get(
                    surcharge.status,
                    surcharge.status,
                )
                surcharge_rows.append(
                    {
                        'surcharge_id': surcharge.surcharge_id,
                        'transaction_no': (
                            surcharge.transaction_no
                            or f'SST-{str(surcharge.surcharge_id)[:8].upper()}'
                        ),
                        'shipment_ref': shipment.shipment_no,
                        'booking_ref': shipment.booking.booking_no if shipment.booking_id else '',
                        'client': client_account_label(shipment.client_account),
                        'date': surcharge.transaction_date or surcharge.created_at,
                        'service': service_label,
                        'total_amount': surcharge.subtotal,
                        'status': status_label or 'Draft',
                        'attachment_name': (
                            os.path.basename(surcharge.attachment_file.name)
                            if surcharge.attachment_file
                            else ''
                        ),
                    }
                )

            total_count = paginator.count
            context.update(
                {
                    'surcharge_rows': surcharge_rows,
                    'surcharge_page': page_obj,
                    'surcharge_search_q': search_q,
                    'pagination_total': total_count,
                    'pagination_start': page_obj.start_index() if total_count else 0,
                    'pagination_end': page_obj.end_index() if total_count else 0,
                    'surcharge_stats': {
                        'total': TenantShipmentSurcharge.objects.count(),
                        'draft': TenantShipmentSurcharge.objects.filter(
                            status=TenantShipmentSurcharge.Status.DRAFT,
                        ).count(),
                        'confirmed': TenantShipmentSurcharge.objects.filter(
                            status=TenantShipmentSurcharge.Status.CONFIRMED,
                        ).count(),
                        'invoiced': TenantShipmentSurcharge.objects.filter(
                            status=TenantShipmentSurcharge.Status.INVOICED,
                        ).count(),
                        'cancelled': TenantShipmentSurcharge.objects.filter(
                            status=TenantShipmentSurcharge.Status.CANCELLED,
                        ).count(),
                    },
                    'tenant_schema_name': tenant_registry.schema_name,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()


def _tenant_surcharge_sales_options_context(tenant_registry):
    shipment_options = []
    for shipment in TenantShipment.objects.select_related(
        'booking',
        'client_account',
    ).exclude(
        shipment_status=TenantShipment.ShipmentStatus.CANCELLED,
    ).order_by('-created_at')[:500]:
        client_ref = client_account_label(shipment.client_account)
        booking_no = shipment.booking.booking_no if shipment.booking_id and shipment.booking else ''
        booking_item_ref = (shipment.booking_item_ref or '').strip()
        shipment_label_parts = [part for part in [shipment.shipment_no, booking_no, client_ref] if part]
        booking_label_parts = [part for part in [booking_no, booking_item_ref] if part]
        currency_code = _tenant_surcharge_sales_currency_from_shipment(shipment)
        currency_label = currency_code
        currency_row = Currency.objects.filter(
            currency_code=currency_code,
            is_active=True,
        ).values('name_en').first()
        if currency_row and currency_row.get('name_en'):
            currency_label = f'{currency_code} - {currency_row["name_en"]}'
        shipment_options.append(
            {
                'shipment_id': str(shipment.shipment_id),
                'shipment_no': shipment.shipment_no,
                'shipment_label': ' - '.join(shipment_label_parts) or shipment.shipment_no,
                'booking_id': str(shipment.booking_id) if shipment.booking_id else '',
                'booking_no': booking_no,
                'booking_label': ' - '.join(booking_label_parts) or booking_no,
                'client_account_id': str(shipment.client_account_id) if shipment.client_account_id else '',
                'client_account_ref': client_ref,
                'currency_code': currency_code,
                'currency_label': currency_label,
            }
        )

    service_options = list(
        TenantServiceItemMaster.objects.filter(
            service_type=TenantServiceItemMaster.ServiceType.SERVICE,
            status=TenantServiceItemMaster.Status.ACTIVE,
        ).order_by('service_code')
    )

    booking_options = []
    for booking in TenantBooking.objects.select_related('client_account').exclude(
        booking_status=TenantBooking.Status.CANCELLED,
    ).order_by('-created_at')[:500]:
        client_ref = client_account_label(booking.client_account)
        label_parts = [part for part in [booking.booking_no, client_ref] if part]
        booking_options.append(
            {
                'booking_id': str(booking.booking_id),
                'label': ' - '.join(label_parts) or booking.booking_no,
            }
        )

    client_options = []
    for account in TenantClientAccount.objects.filter(
        status=TenantClientAccount.Status.ACTIVE,
    ).order_by('account_no')[:500]:
        client_options.append(
            {
                'client_account_id': str(account.account_id),
                'label': client_account_label(account),
                'preferred_currency': (account.preferred_currency or 'SAR')[:8],
            }
        )

    currency_options = []
    for row in _active_currency_options():
        code = row.get('currency_code') or ''
        name_en = (row.get('name_en') or '').strip()
        currency_options.append(
            {
                'currency_code': code,
                'label': f'{code} - {name_en}' if name_en else code,
            }
        )

    return {
        'shipment_options': shipment_options,
        'booking_options': booking_options,
        'client_options': client_options,
        'currency_options': currency_options,
        'service_options': service_options,
        'tenant_schema_name': tenant_registry.schema_name,
    }


class TenantOperationSurchargeSalesCreateView(View):
    template_name = 'iroad_tenants/Operation_management/Surcharge/Surcharge-sales-transaction-create.html'

    def get(self, request, mode=None):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            page_mode = (mode or 'create').strip().lower()
            context['surcharge_mode'] = page_mode
            surcharge_id = (request.GET.get('surcharge_id') or '').strip()
            surcharge = None
            if surcharge_id:
                surcharge = (
                    TenantShipmentSurcharge.objects.select_related(
                        'shipment',
                        'service_item',
                        'booking',
                        'client_account',
                    )
                    .filter(pk=surcharge_id)
                    .first()
                )
            if surcharge is not None:
                context['surcharge_form_data'] = _tenant_surcharge_sales_form_data_from_surcharge(surcharge)
                if page_mode == 'view':
                    context['surcharge_form_data']['page_mode'] = 'view'
                context['preview_surcharge_transaction_no'] = (
                    surcharge.transaction_no
                    or f'SST-{str(surcharge.surcharge_id)[:8].upper()}'
                )
            else:
                context.setdefault(
                    'surcharge_form_data',
                    {
                        'page_mode': page_mode,
                        'trx_date': timezone.localdate().isoformat(),
                        'quantity': '1',
                        'unit_price': '0.00',
                        'total_amount': '0.00',
                        'status': TenantShipmentSurcharge.Status.DRAFT,
                        'booking_id': '',
                        'client_account_id': '',
                        'currency_code': '',
                    },
                )
                context['preview_surcharge_transaction_no'] = _preview_next_auto_number_for_form(
                    form_code=SURCHARGE_SALES_AUTO_FORM_CODE,
                    form_label=SURCHARGE_SALES_AUTO_FORM_LABEL,
                    prefix=SURCHARGE_SALES_REF_PREFIX,
                )
            context.update(_tenant_surcharge_sales_options_context(tenant_registry))
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()

    def post(self, request, mode=None):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            form_data = {
                'surcharge_id': (request.POST.get('surcharge_id') or '').strip(),
                'page_mode': (request.POST.get('page_mode') or mode or 'create').strip().lower(),
                'trx_date': (request.POST.get('trx_date') or '').strip(),
                'shipment_id': (request.POST.get('shipment_id') or '').strip(),
                'booking_id': (request.POST.get('booking_id') or '').strip(),
                'client_account_id': (request.POST.get('client_account_id') or '').strip(),
                'currency_code': (request.POST.get('currency_code') or '').strip(),
                'service_item_id': (request.POST.get('service_item_id') or '').strip(),
                'description': (request.POST.get('description') or '').strip(),
                'quantity': (request.POST.get('quantity') or '').strip(),
                'unit_price': (request.POST.get('unit_price') or '').strip(),
                'total_amount': (request.POST.get('total_amount') or '').strip(),
                'status': (request.POST.get('status') or TenantShipmentSurcharge.Status.DRAFT).strip(),
                'notes': (request.POST.get('notes') or '').strip(),
            }
            existing_surcharge = None
            if form_data['surcharge_id']:
                existing_surcharge = TenantShipmentSurcharge.objects.filter(
                    pk=form_data['surcharge_id'],
                ).first()

            (
                form_errors,
                transaction_date,
                shipment,
                service_item,
                quantity,
                unit_price,
                total_amount,
                currency,
                upload,
            ) = _tenant_surcharge_sales_validate_submission(
                request,
                form_data,
                existing_surcharge=existing_surcharge,
            )
            form_data['total_amount'] = str(total_amount)

            if form_errors or transaction_date is None or shipment is None or service_item is None:
                context.update(
                    {
                        'surcharge_mode': form_data['page_mode'],
                        'surcharge_form_data': form_data,
                        'form_errors': form_errors,
                        'preview_surcharge_transaction_no': _preview_next_auto_number_for_form(
                            form_code=SURCHARGE_SALES_AUTO_FORM_CODE,
                            form_label=SURCHARGE_SALES_AUTO_FORM_LABEL,
                            prefix=SURCHARGE_SALES_REF_PREFIX,
                        ),
                    }
                )
                context.update(_tenant_surcharge_sales_options_context(tenant_registry))
                messages.error(request, 'Please fix the highlighted surcharge fields.', extra_tags='tenant')
                return render(request, self.template_name, context)

            with db_transaction.atomic():
                if existing_surcharge is not None:
                    surcharge = existing_surcharge
                    surcharge.transaction_date = transaction_date
                    surcharge.status = form_data['status']
                    surcharge.description = form_data['description'][:255]
                    surcharge.qty = quantity
                    surcharge.unit_price = unit_price
                    surcharge.subtotal = total_amount
                    surcharge.reason = form_data['notes']
                    if upload is not None:
                        surcharge.attachment_file = upload
                    _tenant_surcharge_sales_apply_foreign_keys(
                        surcharge,
                        shipment=shipment,
                        service_item=service_item,
                        booking_id=form_data.get('booking_id', ''),
                        client_account_id=form_data.get('client_account_id', ''),
                        currency=currency,
                    )
                    surcharge.save()
                else:
                    transaction_no, transaction_sequence = _next_auto_number_for_form(
                        form_code=SURCHARGE_SALES_AUTO_FORM_CODE,
                        form_label=SURCHARGE_SALES_AUTO_FORM_LABEL,
                        prefix=SURCHARGE_SALES_REF_PREFIX,
                    )
                    last_line_no = (
                        TenantShipmentSurcharge.objects.filter(shipment=shipment)
                        .order_by('-line_no')
                        .values_list('line_no', flat=True)
                        .first()
                        or 0
                    )
                    surcharge = TenantShipmentSurcharge(
                        transaction_no=transaction_no,
                        transaction_sequence=transaction_sequence,
                        transaction_date=transaction_date,
                        status=form_data['status'],
                        line_no=int(last_line_no) + 1,
                        description=form_data['description'][:255],
                        qty=quantity,
                        unit_price=unit_price,
                        subtotal=total_amount,
                        currency=currency,
                        reason=form_data['notes'],
                        attachment_file=upload,
                    )
                    _tenant_surcharge_sales_apply_foreign_keys(
                        surcharge,
                        shipment=shipment,
                        service_item=service_item,
                        booking_id=form_data.get('booking_id', ''),
                        client_account_id=form_data.get('client_account_id', ''),
                        currency=currency,
                    )
                    surcharge.save()
            messages.success(request, 'Surcharge transaction saved for the selected shipment and service.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_operation_surcharge_sales_list')
        finally:
            connection.set_schema_to_public()


class TenantWebPushTokenUpsertView(View):
    """Register/update browser push token for the logged-in tenant portal user."""

    def post(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            return JsonResponse({'ok': False, 'error': 'unauthorized'}, status=401)
        try:
            payload = json.loads(request.body or '{}')
        except json.JSONDecodeError:
            return JsonResponse({'ok': False, 'error': 'invalid_json'}, status=400)

        token = str(payload.get('device_token') or '').strip()
        if not token:
            return JsonResponse({'ok': False, 'error': 'device_token_required'}, status=400)

        auth_payload = get_tenant_portal_cookie_payload(request) or {}
        tenant_id = str(auth_payload.get('tenant_id') or '').strip()
        tenant_jti = str(auth_payload.get('jti') or '').strip()
        session_data = get_tenant_session(tenant_id, tenant_jti) if (tenant_id and tenant_jti) else {}
        session_data = session_data or {}

        reference_id = str(
            session_data.get('reference_id') or getattr(context.get('tenant'), 'tenant_id', '')
        ).strip()
        user_domain = str(session_data.get('user_domain') or 'Tenant_User').strip()
        if user_domain not in ('Tenant_User', 'Driver', 'Admin'):
            user_domain = 'Tenant_User'

        obj, _created = PushDeviceToken.objects.update_or_create(
            device_token=token,
            defaults={
                'tenant': context['tenant'],
                'user_domain': user_domain,
                'reference_id': reference_id,
                'is_active': True,
            },
        )
        return JsonResponse(
            {
                'ok': True,
                'token_id': str(obj.token_id),
                'user_domain': obj.user_domain,
                'reference_id': obj.reference_id,
                'is_active': obj.is_active,
            },
            status=200,
        )


def _get_singleton_client_account_settings():
    """Single settings row for the active tenant schema (isolated per-tenant DB).

    Prefer the most recently updated row so we never read stale flags if duplicate
    rows ever existed; settings POST success path consolidates to one row.
    """
    row = TenantClientAccountSetting.objects.order_by('-updated_at').first()
    if row is None:
        row = TenantClientAccountSetting.objects.create()
    return row


def _client_account_settings_template_dict(settings_obj):
    return {
        'require_national_id_individual': settings_obj.require_national_id_individual,
        'require_commercial_registration_business': (
            settings_obj.require_commercial_registration_business
        ),
        'require_tax_vat_registration_business': settings_obj.require_tax_vat_registration_business,
        'default_client_status': settings_obj.default_client_status,
        'default_client_type': settings_obj.default_client_type,
        'default_preferred_currency': settings_obj.default_preferred_currency or '',
    }


def _apply_client_account_defaults_from_settings(form_data, settings_obj):
    """Pre-fill new-client form from tenant-scoped Client Account Settings."""
    if settings_obj.default_client_status:
        form_data['status'] = settings_obj.default_client_status
    if settings_obj.default_client_type:
        form_data['client_type'] = settings_obj.default_client_type
    default_cur = (settings_obj.default_preferred_currency or '').strip()
    if default_cur:
        form_data['preferred_currency'] = default_cur


def _validate_client_account_document_rules(form_data, settings_obj, form_errors):
    """Enforce National ID / CR / VAT rules from the current tenant's settings."""
    from tenant_workspace.client_account_document_rules import (
        collect_client_account_document_rule_errors,
    )

    form_errors.update(
        collect_client_account_document_rule_errors(
            client_type=form_data.get('client_type'),
            national_id=form_data.get('national_id'),
            commercial_registration_no=form_data.get('commercial_registration_no'),
            tax_registration_no=form_data.get('tax_registration_no'),
            require_national_id_individual=bool(settings_obj.require_national_id_individual),
            require_commercial_registration_business=bool(
                settings_obj.require_commercial_registration_business
            ),
            require_tax_vat_registration_business=bool(
                settings_obj.require_tax_vat_registration_business
            ),
        )
    )


def _merge_validation_error_into_form_errors(exc, form_errors):
    """Map Django ``ValidationError`` (e.g. from ``TenantClientAccount.save``) to form field errors."""
    if hasattr(exc, 'message_dict') and exc.message_dict:
        for field, msgs in exc.message_dict.items():
            if isinstance(msgs, (list, tuple)) and msgs:
                form_errors[field] = str(msgs[0])
            elif msgs:
                form_errors[field] = str(msgs)
            else:
                form_errors[field] = str(exc)
    elif getattr(exc, 'messages', None):
        joined = '; '.join(str(m) for m in exc.messages)
        form_errors.setdefault('__all__', joined)


class TenantClientAccountView(View):
    """List client accounts from the current tenant workspace schema."""

    template_name = 'iroad_tenants/Clients_Management/Client-account.html'

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            search_q = (request.GET.get('q') or '').strip()
            qs = TenantClientAccount.objects.all()
            if search_q:
                qs = qs.filter(
                    Q(account_no__icontains=search_q)
                    | Q(name_english__icontains=search_q)
                    | Q(display_name__icontains=search_q)
                    | Q(name_arabic__icontains=search_q)
                    | Q(preferred_currency__icontains=search_q),
                )
            client_accounts = list(qs.order_by('account_no'))
            context.update(
                {
                    'client_accounts': client_accounts,
                    'client_accounts_count': len(client_accounts),
                    'tenant_schema_name': tenant_registry.schema_name,
                    'search_q': search_q,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()


class TenantClientAccountSettingsView(View):
    """Load/save client CRM defaults in the current tenant workspace schema only."""

    template_name = 'iroad_tenants/Clients_Management/Client-account-setting.html'

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            settings_obj = _get_singleton_client_account_settings()
            context.update(
                {
                    'settings_data': _client_account_settings_template_dict(settings_obj),
                    'settings_errors': {},
                    'currency_options': _active_currency_options(),
                    'tenant_schema_name': tenant_registry.schema_name,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()

    def post(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            settings_data = {
                'require_national_id_individual': bool(
                    request.POST.get('require_national_id_individual')
                ),
                'require_commercial_registration_business': bool(
                    request.POST.get('require_commercial_registration_business')
                ),
                'require_tax_vat_registration_business': bool(
                    request.POST.get('require_tax_vat_registration_business')
                ),
                'default_client_status': (request.POST.get('default_client_status') or '').strip()
                or TenantClientAccount.Status.ACTIVE,
                'default_client_type': (request.POST.get('default_client_type') or '').strip()
                or TenantClientAccount.ClientType.INDIVIDUAL,
                'default_preferred_currency': (request.POST.get('default_preferred_currency') or '').strip(),
            }
            settings_errors = {}
            if settings_data['default_client_status'] not in {
                TenantClientAccount.Status.ACTIVE,
                TenantClientAccount.Status.INACTIVE,
            }:
                settings_errors['default_client_status'] = 'Invalid default status.'
            if settings_data['default_client_type'] not in {
                TenantClientAccount.ClientType.INDIVIDUAL,
                TenantClientAccount.ClientType.BUSINESS,
            }:
                settings_errors['default_client_type'] = 'Invalid default client type.'
            if settings_data['default_preferred_currency']:
                valid_codes = {
                    c['currency_code'] for c in _active_currency_options()
                }
                if settings_data['default_preferred_currency'] not in valid_codes:
                    settings_errors['default_preferred_currency'] = (
                        'Choose an active currency from the list, or leave the default currency empty.'
                    )

            if settings_errors:
                context.update(
                    {
                        'settings_data': settings_data,
                        'settings_errors': settings_errors,
                        'currency_options': _active_currency_options(),
                        'tenant_schema_name': tenant_registry.schema_name,
                    }
                )
                messages.error(
                    request,
                    'Please fix the highlighted errors.',
                    extra_tags='tenant',
                )
                return render(request, self.template_name, context)

            keeper = TenantClientAccountSetting.objects.order_by('-updated_at').first()
            if keeper is None:
                keeper = TenantClientAccountSetting.objects.create()
            else:
                TenantClientAccountSetting.objects.exclude(pk=keeper.pk).delete()
            settings_obj = keeper
            settings_obj.require_national_id_individual = settings_data[
                'require_national_id_individual'
            ]
            settings_obj.require_commercial_registration_business = settings_data[
                'require_commercial_registration_business'
            ]
            settings_obj.require_tax_vat_registration_business = settings_data[
                'require_tax_vat_registration_business'
            ]
            settings_obj.default_client_status = settings_data['default_client_status']
            settings_obj.default_client_type = settings_data['default_client_type']
            settings_obj.default_preferred_currency = settings_data['default_preferred_currency']
            settings_obj.save()
            messages.success(
                request,
                'Client account settings saved for this workspace.',
                extra_tags='tenant',
            )
            return _tenant_redirect(request, 'iroad_tenants:tenant_client_account_settings')
        finally:
            connection.set_schema_to_public()


class TenantClientAccountCreateView(View):
    template_name = 'iroad_tenants/Clients_Management/Client-account-new.html'

    CLIENT_FORM_CODE = 'client-account'
    CLIENT_FORM_LABEL = 'Client Account'
    CLIENT_REF_PREFIX = 'CA'

    def _base_form_data(self):
        return {
            'account_no': '',
            'created_at': timezone.localtime().strftime('%b %d, %Y, %I:%M %p'),
            'client_type': TenantClientAccount.ClientType.INDIVIDUAL,
            'status': TenantClientAccount.Status.ACTIVE,
            'name_arabic': '',
            'name_english': '',
            'display_name': '',
            'preferred_currency': '',
            'billing_street_1': '',
            'billing_street_2': '',
            'billing_city': '',
            'billing_region': '',
            'postal_code': '',
            'country': '',
            'credit_limit_amount': '',
            'limit_currency_code': 'SAR',
            'payment_term_days': '',
            'national_id': '',
            'commercial_registration_no': '',
            'tax_registration_no': '',
        }

    def _collect_form_data(self, request):
        data = self._base_form_data()
        for key in data.keys():
            if key in {'status', 'client_type'}:
                data[key] = (request.POST.get(key) or '').strip() or data[key]
            else:
                data[key] = (request.POST.get(key) or '').strip()
        data['limit_currency_code'] = data['limit_currency_code'] or 'SAR'
        return data

    def _build_preview_account_no(self):
        config, _ = AutoNumberConfiguration.objects.get_or_create(
            form_code=self.CLIENT_FORM_CODE,
            defaults={
                'form_label': self.CLIENT_FORM_LABEL,
                'number_of_digits': 4,
                'sequence_format': AutoNumberConfiguration.SequenceFormat.NUMERIC,
                'is_unique': True,
            },
        )
        sequence = AutoNumberSequence.objects.filter(form_code=self.CLIENT_FORM_CODE).first()
        next_number = int(sequence.next_number if sequence else 1)
        return _render_tenant_ref_no(next_number, config, prefix=self.CLIENT_REF_PREFIX)

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            settings_obj = _get_singleton_client_account_settings()
            form_data = self._base_form_data()
            form_data['account_no'] = self._build_preview_account_no()
            _apply_client_account_defaults_from_settings(form_data, settings_obj)
            context.update(
                {
                    'form_data': form_data,
                    'form_errors': {},
                    'tenant_schema_name': tenant_registry.schema_name,
                    'currency_options': _active_currency_options(),
                    'settings_data': _client_account_settings_template_dict(settings_obj),
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()

    def post(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        form_data = self._collect_form_data(request)
        form_errors = {}
        try:
            settings_obj = _get_singleton_client_account_settings()
            if form_data['client_type'] not in {
                TenantClientAccount.ClientType.INDIVIDUAL,
                TenantClientAccount.ClientType.BUSINESS,
            }:
                form_errors['client_type'] = 'Invalid client type selected.'
            if form_data['status'] not in {
                TenantClientAccount.Status.ACTIVE,
                TenantClientAccount.Status.INACTIVE,
            }:
                form_errors['status'] = 'Invalid status selected.'
            if not form_data['name_english']:
                form_errors['name_english'] = 'Name (English) is required.'
            if not form_data['display_name']:
                form_errors['display_name'] = 'Display Name is required.'
            if not form_data['preferred_currency']:
                form_errors['preferred_currency'] = 'Preferred Currency is required.'
            if not form_data['billing_street_1']:
                form_errors['billing_street_1'] = 'Billing Street 1 is required.'
            if not form_data['billing_city']:
                form_errors['billing_city'] = 'Billing City is required.'
            if not form_data['country']:
                form_errors['country'] = 'Country is required.'
            if not form_errors.get('client_type'):
                _validate_client_account_document_rules(form_data, settings_obj, form_errors)

            credit_limit_raw = form_data['credit_limit_amount'] or '0'
            payment_term_raw = form_data['payment_term_days'] or '0'
            try:
                credit_limit_amount = Decimal(credit_limit_raw)
                if credit_limit_amount < 0:
                    raise ValueError
            except Exception:
                form_errors['credit_limit_amount'] = 'Credit Limit Amount must be 0 or greater.'
                credit_limit_amount = Decimal('0')
            try:
                payment_term_days = int(payment_term_raw)
                if payment_term_days < 0:
                    raise ValueError
            except Exception:
                form_errors['payment_term_days'] = 'Payment Term (Days) must be 0 or greater.'
                payment_term_days = 0

            if form_errors:
                form_data['account_no'] = self._build_preview_account_no()
                context.update(
                    {
                        'form_data': form_data,
                        'form_errors': form_errors,
                        'tenant_schema_name': tenant_registry.schema_name,
                        'currency_options': _active_currency_options(),
                        'settings_data': _client_account_settings_template_dict(settings_obj),
                    }
                )
                messages.error(request, 'Please fix the highlighted errors.', extra_tags='tenant')
                return render(request, self.template_name, context)

            account_no, account_sequence = _next_auto_number_for_form(
                form_code=self.CLIENT_FORM_CODE,
                form_label=self.CLIENT_FORM_LABEL,
                prefix=self.CLIENT_REF_PREFIX,
            )
            try:
                TenantClientAccount.objects.create(
                    account_no=account_no,
                    account_sequence=account_sequence,
                    client_type=form_data['client_type'],
                    status=form_data['status'],
                    name_arabic=form_data['name_arabic'],
                    name_english=form_data['name_english'],
                    display_name=form_data['display_name'],
                    preferred_currency=form_data['preferred_currency'],
                    billing_street_1=form_data['billing_street_1'],
                    billing_street_2=form_data['billing_street_2'],
                    billing_city=form_data['billing_city'],
                    billing_region=form_data['billing_region'],
                    postal_code=form_data['postal_code'],
                    country=form_data['country'],
                    credit_limit_amount=credit_limit_amount,
                    limit_currency_code=form_data['limit_currency_code'] or 'SAR',
                    payment_term_days=payment_term_days,
                    national_id=form_data['national_id'],
                    commercial_registration_no=form_data['commercial_registration_no'],
                    tax_registration_no=form_data['tax_registration_no'],
                    created_by_label=(context.get('display_name') or '').strip(),
                )
            except ValidationError as exc:
                _merge_validation_error_into_form_errors(exc, form_errors)
                form_data['account_no'] = self._build_preview_account_no()
                context.update(
                    {
                        'form_data': form_data,
                        'form_errors': form_errors,
                        'tenant_schema_name': tenant_registry.schema_name,
                        'currency_options': _active_currency_options(),
                        'settings_data': _client_account_settings_template_dict(settings_obj),
                    }
                )
                messages.error(request, 'Please fix the highlighted errors.', extra_tags='tenant')
                return render(request, self.template_name, context)
            messages.success(
                request,
                f'Client account {account_no} created successfully.',
                extra_tags='tenant',
            )
            return _tenant_redirect(request, 'iroad_tenants:tenant_client_account')
        finally:
            connection.set_schema_to_public()


